//! `os.lazy.usb.bt.v1` (`idl/usb_bt.midl`, docs/bluetooth-plan.md B2): the
//! USB Bluetooth controller `usbd` moves packets for, as `btd` talks to it.
//!
//! The stubs are generated by `midlc`; this module adds the service name, the
//! request framing and the blocking [`Client`] `btd` uses. Packets never cross
//! the wire: the client creates one shared buffer holding both rings
//! ([`Client::attach`]), hands it to `usbd` with a notify endpoint, and then
//! moves ring frames (a packet-kind byte and the packet, `libs/btusb`),
//! waking `usbd` with `Kick` and being woken by `Notify`. Failures come back
//! as the shared structured error field.

use alloc::vec;
use alloc::vec::Vec;

use framering::{ring_bytes, valid_slots, Consumer, Producer, Ring};
use libmessenger::{flags, Buffer, Header, Object, Parcel, VERSION};

use super::services::error_field;
use super::{create_pair, registry, Endpoint, Error, Result};
use crate::sys;

/// The generated stubs.
pub use messenger_generated::os_lazy_usb_bt_v1 as wire;

pub use wire::{Device, Stats};

/// The name `usbd` registers while a Bluetooth controller is bound.
pub const NAME: &str = "os.lazy.usb.bt";

/// The interface id every parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// Slots per ring `btd` asks for: 64 frames of burst each way (about 270 KiB
/// of shared buffer), enough for an inquiry's or a scan's burst of reports
/// while `btd` is busy elsewhere.
pub const SLOTS: u32 = 64;

/// A parcel of `method` carrying an encoded `body` and its `objects` (only
/// `AttachRing` carries any).
pub fn parcel(method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A one-way event parcel (`Kick`, `Notify`).
pub fn event(method: u32, body: Vec<u8>) -> Parcel {
    let mut parcel = parcel(method, body, Vec::new());
    parcel.header.flags = flags::ONE_WAY;
    parcel
}

/// A blocking client of `usbd`'s Bluetooth transport.
pub struct Client {
    endpoint: Endpoint,
}

impl Client {
    /// Resolve [`NAME`]: `ENOENT` (or another error) while no controller is
    /// bound.
    pub fn connect() -> Result<Client> {
        Ok(Client {
            endpoint: registry::resolve(NAME)?,
        })
    }

    /// Give up the handle: it was obtained by name, so it is released, not
    /// closed (closing would end `usbd`'s service side).
    pub fn release(self) {
        let _ = self.endpoint.release();
    }

    fn call(&self, request: Parcel) -> Result<Parcel> {
        let reply = self.endpoint.call(&request, None)?;
        match error_field(&reply)? {
            Some(code) => Err(Error::Errno(-code)),
            None => Ok(reply),
        }
    }

    /// Send an arbitrary request (hostile-input tests): everything goes out
    /// as given, and a service failure still comes back as its errno.
    pub fn raw(&self, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Result<Parcel> {
        self.call(parcel(method, body, objects))
    }

    pub fn describe(&self) -> Result<Device> {
        let reply = self.call(parcel(wire::METHOD_DESCRIBE, Vec::new(), Vec::new()))?;
        Ok(wire::decode_describe_reply(&reply.body)
            .map_err(Error::Parcel)?
            .device)
    }

    pub fn stats(&self) -> Result<Stats> {
        let reply = self.call(parcel(wire::METHOD_STATS, Vec::new(), Vec::new()))?;
        Ok(wire::decode_stats_reply(&reply.body)
            .map_err(Error::Parcel)?
            .stats)
    }

    /// `DetachRing(ring)`.
    pub fn detach(&self, ring: u32) -> Result<()> {
        let body =
            wire::encode_detach_ring_args(&wire::DetachRingArgs { ring }).map_err(Error::Parcel)?;
        self.call(parcel(wire::METHOD_DETACHRING, body, Vec::new()))
            .map(|_| ())
    }

    /// `Kick(ring)`: tell `usbd` frames are waiting in the `Commands` ring.
    pub fn kick(&self, ring: u32) -> Result<()> {
        let body = wire::encode_kick_args(&wire::KickArgs { ring }).map_err(Error::Parcel)?;
        self.endpoint.send(&event(wire::METHOD_KICK, body))
    }

    /// Create both rings in one shared buffer and a fresh notify endpoint, and
    /// attach them. `usbd` keeps the other side of the endpoint; the client
    /// waits on its own with [`Attachment::wait`].
    pub fn attach(&self, slots: u32) -> Result<Attachment> {
        let (mine, theirs) = create_pair()?;
        let result = self.attach_inner(slots, theirs.handle(), mine);
        if result.is_err() {
            // `usbd` never took the far end, or closed its copy.
            let _ = mine.close();
            let _ = theirs.close();
        }
        result
    }

    fn attach_inner(&self, slots: u32, transfer: u64, mine: Endpoint) -> Result<Attachment> {
        if !valid_slots(slots) {
            return Err(Error::Errno(-super::errno::EINVAL));
        }
        let one = ring_bytes(slots);
        let layout =
            wire::attach_ring_rings(one as u64).ok_or(Error::Errno(-super::errno::EINVAL))?;
        let len = layout.total as usize;
        let (buffer, va, _) = sys::buffer_create(len as u64).map_err(|code| Error::Errno(-code))?;
        let base = va as *mut u8;
        // SAFETY: the kernel mapped `len` zeroed bytes at `va`; each ring is
        // `one` bytes at an offset the layout keeps inside `len`, and the
        // mapping lives until `Attachment::close`.
        let (commands, events) = unsafe {
            let commands = Ring::create(base.add(layout.commands as usize), one, slots);
            let events = Ring::create(base.add(layout.events as usize), one, slots);
            (commands, events)
        };
        let (Ok(commands), Ok(events)) = (commands, events) else {
            let _ = sys::buffer_close(buffer);
            return Err(Error::Errno(-super::errno::EINVAL));
        };
        let (body, objects) = wire::encode_attach_ring_args(&wire::AttachRingArgs {
            slots,
            rings: Buffer::whole(buffer, len as u64),
            notify: transfer,
        })
        .map_err(Error::Parcel)?;
        match self.call(parcel(wire::METHOD_ATTACHRING, body, objects)) {
            Ok(reply) => {
                let ring = wire::decode_attach_ring_reply(&reply.body)
                    .map_err(Error::Parcel)?
                    .ring;
                Ok(Attachment {
                    ring,
                    slots,
                    buffer,
                    notify: mine,
                    events: events.consumer(),
                    commands: commands.producer(),
                    buf: vec![0; 256],
                })
            }
            Err(error) => {
                let _ = sys::buffer_close(buffer);
                Err(error)
            }
        }
    }
}

/// A client's attachment: its ends of the two rings and its notify endpoint.
pub struct Attachment {
    pub ring: u32,
    pub slots: u32,
    buffer: u64,
    notify: Endpoint,
    /// Frames from the controller: this client consumes.
    pub events: Consumer,
    /// Frames to the controller: this client produces.
    pub commands: Producer,
    buf: Vec<u8>,
}

impl Attachment {
    /// Wait for a `Notify` until the absolute tick `deadline`. `Ok(Some(bits))`
    /// carries the `NotifyBit` bitmap, `Ok(None)` a timeout. A message that is
    /// not a well-formed `Notify` is ignored, as a hostile sender could send
    /// one. Arm the `events` ring (and look once more) before calling this, or
    /// `usbd` sends no doorbell.
    pub fn wait(&mut self, deadline: u64) -> Result<Option<u32>> {
        match self.notify.recv_with(&mut self.buf, Some(deadline)) {
            Ok(message) => {
                if message.interface_id() == INTERFACE && message.method() == wire::METHOD_NOTIFY {
                    if let Ok(args) = wire::decode_notify_args(&message.parcel.body) {
                        return Ok(Some(args.events));
                    }
                }
                Ok(Some(0))
            }
            Err(Error::Errno(code)) if code == -super::errno::ETIMEDOUT => Ok(None),
            Err(error) => Err(error),
        }
    }

    /// [`Attachment::wait`], also ending when `other` has a message or its
    /// peer closed (a service that shares the loop). Nothing is received from
    /// `other`: the caller takes what is ready.
    pub fn wait_with(&mut self, other: Option<Endpoint>, deadline: u64) -> Result<Option<u32>> {
        let Some(other) = other else {
            return self.wait(deadline);
        };
        match super::wait::wait_any(&[self.notify, other], 0, Some(deadline)) {
            // The notify endpoint is ready: read it (it returns at once).
            Ok(ready) if ready & 1 != 0 => self.wait(deadline),
            Ok(_) => Ok(Some(0)),
            Err(Error::Errno(code)) if code == -super::errno::ETIMEDOUT => Ok(None),
            Err(error) => Err(error),
        }
    }

    /// Release the shared buffer and the notify endpoint. Call
    /// [`Client::detach`] first to release `usbd`'s side.
    pub fn close(self) {
        let _ = sys::buffer_close(self.buffer);
        let _ = self.notify.close();
    }
}
